import{_ as e,o as d,c as a,ag as s}from"./chunks/framework.DGzMGr_a.js";const g=JSON.parse('{"title":"GTPet 使用教程","description":"","frontmatter":{},"headers":[],"relativePath":"gtpet/index.md","filePath":"gtpet/index.md","lastUpdated":1785597572000}'),o={name:"gtpet/index.md"};function l(i,t,p,c,r,n){return d(),a("div",null,[...t[0]||(t[0]=[s(`<h1 id="gtpet-使用教程" tabindex="-1">GTPet 使用教程 <a class="header-anchor" href="#gtpet-使用教程" aria-label="Permalink to &quot;GTPet 使用教程&quot;">​</a></h1><p>本页带你从安装完成走到成功发放、召唤和操作第一只宠物。所有配置文件都位于：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>plugins/GTCore/modules/GTPet/</span></span></code></pre></div><h2 id="安装" tabindex="-1">安装 <a class="header-anchor" href="#安装" aria-label="Permalink to &quot;安装&quot;">​</a></h2><ol><li>安装服务器对应版本的 GTCore。</li><li>将 GTPet 模块 JAR 放入 GTCore 的模块目录。</li><li>启动服务器，等待控制台出现 GTPet 配置加载成功提示。</li><li>关闭服务器或确认没有玩家正在操作宠物后，再修改生成的 YAML。</li></ol><p>支持的服务器范围包括 Spigot 1.12.2、CatServer 1.12.2、Purpur、Paper 和 Folia。Java 版本按服务器核心要求选择。</p><h2 id="配置文件" tabindex="-1">配置文件 <a class="header-anchor" href="#配置文件" aria-label="Permalink to &quot;配置文件&quot;">​</a></h2><p>首次加载后会生成以下文件：</p><table tabindex="0"><thead><tr><th>文件</th><th>配置内容</th></tr></thead><tbody><tr><td><code>config.yml</code></td><td>存储、宠物数量、下线收回、改名、模块开关</td></tr><tr><td><code>templates.yml</code></td><td>宠物模板、品质池、基础属性、技能、基因、装备槽、工作</td></tr><tr><td><code>coefficients.yml</code></td><td>战斗、移动、资源、成长、繁育和工作数值</td></tr><tr><td><code>overrides.yml</code></td><td>按世界、模板、品质、姿态、权限等条件覆盖系数</td></tr><tr><td><code>messages.yml</code></td><td>玩家提示、状态名称、品质名称、错误提示</td></tr><tr><td><code>skills.yml</code></td><td>技能目标、消耗、冷却、范围和效果类型</td></tr><tr><td><code>breeding.yml</code></td><td>基因、繁育限制和进化路线</td></tr><tr><td><code>attributes.yml</code></td><td>属性成长、品质加成、基因/特质加成、装备属性名</td></tr><tr><td><code>display.yml</code></td><td>PLAYER 外观、移动同步和头顶信息</td></tr><tr><td><code>equipment.yml</code></td><td>装备槽位置、允许物品、解锁条件和实体显示位置</td></tr><tr><td><code>jobs.yml</code></td><td>工作类型、周期、消耗、经验和奖励</td></tr><tr><td><code>systems.yml</code></td><td>战斗结算、PVP、成长、工作和联动开关</td></tr><tr><td><code>gui/*.yml</code></td><td>宠物列表、详情、成长、繁育、进化、装备、技能和工作页面</td></tr></tbody></table><h2 id="第一次启动检查" tabindex="-1">第一次启动检查 <a class="header-anchor" href="#第一次启动检查" aria-label="Permalink to &quot;第一次启动检查&quot;">​</a></h2><p>在控制台执行：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gtpet status</span></span>
<span class="line"><span>gtpet templates</span></span></code></pre></div><p>正常结果：</p><ul><li><code>ready</code> 显示为 <code>true</code>。</li><li>存储显示为本地、MySQL 或 Redis。</li><li><code>gtpet templates</code> 能列出 <code>starter_wolf</code>、<code>forest_ocelot</code>、<code>pack_horse</code>、<code>iron_guardian</code> 和 <code>player_companion</code>。</li></ul><p>如果 <code>ready=false</code>，先看同一时间的控制台报错。常见原因是 YAML 缩进错误、存储连接失败、模板引用了不存在的技能/装备槽，或配置值超出允许范围。</p><h2 id="十分钟完成第一只宠物" tabindex="-1">十分钟完成第一只宠物 <a class="header-anchor" href="#十分钟完成第一只宠物" aria-label="Permalink to &quot;十分钟完成第一只宠物&quot;">​</a></h2><p>下面假设在线玩家名为 <code>Steve</code>。</p><h3 id="_1-发放宠物" tabindex="-1">1. 发放宠物 <a class="header-anchor" href="#_1-发放宠物" aria-label="Permalink to &quot;1. 发放宠物&quot;">​</a></h3><p>在控制台或拥有 <code>gtpet.admin.give</code> 权限的管理员账号执行：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gtpet give Steve starter_wolf 1</span></span></code></pre></div><p>管理员和玩家都会收到成功提示，其中包含这只宠物的短 ID。</p><h3 id="_2-打开宠物界面" tabindex="-1">2. 打开宠物界面 <a class="header-anchor" href="#_2-打开宠物界面" aria-label="Permalink to &quot;2. 打开宠物界面&quot;">​</a></h3><p>玩家执行：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/gtpet</span></span></code></pre></div><p>点击宠物条目进入详情页。详情页可以召唤/收回宠物、切换姿态、改名，并进入成长、繁育、进化、技能、装备和工作页面。</p><h3 id="_3-召唤宠物" tabindex="-1">3. 召唤宠物 <a class="header-anchor" href="#_3-召唤宠物" aria-label="Permalink to &quot;3. 召唤宠物&quot;">​</a></h3><p>可以在 GUI 中点击召唤，也可以执行：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/gtpet summon &lt;宠物短ID&gt;</span></span></code></pre></div><p>预期结果：宠物出现在玩家附近，超过跟随距离后自动跟随，距离过远时返回玩家身边。</p><h3 id="_4-切换姿态" tabindex="-1">4. 切换姿态 <a class="header-anchor" href="#_4-切换姿态" aria-label="Permalink to &quot;4. 切换姿态&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/gtpet stance &lt;宠物短ID&gt; DEFENSIVE</span></span></code></pre></div><p>可用姿态由模板的 <code>allowed-stances</code> 决定：</p><table tabindex="0"><thead><tr><th>姿态</th><th>用途</th></tr></thead><tbody><tr><td><code>PASSIVE</code></td><td>不主动战斗，主要跟随主人</td></tr><tr><td><code>DEFENSIVE</code></td><td>主人或宠物受到攻击时反击</td></tr><tr><td><code>AGGRESSIVE</code></td><td>主动寻找允许攻击的目标</td></tr><tr><td><code>HOLD</code></td><td>保持当前位置</td></tr><tr><td><code>WORK</code></td><td>用于工作状态</td></tr></tbody></table><h3 id="_5-收回宠物" tabindex="-1">5. 收回宠物 <a class="header-anchor" href="#_5-收回宠物" aria-label="Permalink to &quot;5. 收回宠物&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/gtpet recall &lt;宠物短ID&gt;</span></span></code></pre></div><p>主人下线时默认也会自动收回宠物：</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">pets</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  recall-on-owner-quit</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span></code></pre></div><h2 id="常用命令" tabindex="-1">常用命令 <a class="header-anchor" href="#常用命令" aria-label="Permalink to &quot;常用命令&quot;">​</a></h2><p>玩家需要 <code>gtpet.use</code> 权限。</p><table tabindex="0"><thead><tr><th>命令</th><th>用途</th></tr></thead><tbody><tr><td><code>/gtpet</code></td><td>打开宠物主界面</td></tr><tr><td><code>/gtpet pets</code></td><td>查看宠物短 ID、品质、等级、状态和姿态</td></tr><tr><td><code>/gtpet templates</code></td><td>查看可用模板</td></tr><tr><td><code>/gtpet summon &lt;宠物&gt;</code></td><td>召唤宠物</td></tr><tr><td><code>/gtpet recall &lt;宠物&gt;</code></td><td>收回宠物</td></tr><tr><td><code>/gtpet revive &lt;宠物&gt;</code></td><td>复活倒地宠物</td></tr><tr><td><code>/gtpet stance &lt;宠物&gt; &lt;姿态&gt;</code></td><td>切换姿态</td></tr><tr><td><code>/gtpet rename &lt;宠物&gt; &lt;名称&gt;</code></td><td>修改名称</td></tr><tr><td><code>/gtpet grow &lt;宠物&gt; &lt;属性&gt; &lt;点数&gt;</code></td><td>分配潜能点</td></tr><tr><td><code>/gtpet reset &lt;宠物&gt;</code></td><td>重置已分配的属性点</td></tr><tr><td><code>/gtpet skill cast &lt;宠物&gt; &lt;技能&gt;</code></td><td>主动施放技能</td></tr><tr><td><code>/gtpet skill learn &lt;宠物&gt; &lt;技能&gt; [点数]</code></td><td>学习或升级技能</td></tr><tr><td><code>/gtpet breed &lt;宠物&gt; &lt;另一只宠物&gt;</code></td><td>繁育幼体</td></tr><tr><td><code>/gtpet evolve &lt;宠物&gt; &lt;进化ID&gt;</code></td><td>执行进化</td></tr><tr><td><code>/gtpet equip &lt;宠物&gt; &lt;槽位&gt; &lt;物品ID&gt;</code></td><td>从背包中按物品 ID 选择并穿戴装备</td></tr><tr><td><code>/gtpet unequip &lt;宠物&gt; &lt;槽位&gt;</code></td><td>卸下装备</td></tr><tr><td><code>/gtpet work start &lt;宠物&gt; &lt;工作ID&gt;</code></td><td>开始工作</td></tr><tr><td><code>/gtpet work stop &lt;宠物&gt;</code></td><td>停止工作</td></tr><tr><td><code>/gtpet claim &lt;宠物&gt; [奖励ID]</code></td><td>领取工作奖励</td></tr></tbody></table><p>管理员权限：</p><table tabindex="0"><thead><tr><th>权限</th><th>用途</th></tr></thead><tbody><tr><td><code>gtpet.admin.give</code></td><td>发放宠物</td></tr><tr><td><code>gtpet.admin.reload</code></td><td>重载配置</td></tr><tr><td><code>gtpet.admin.diagnostics</code></td><td>查看状态、系数和 AI 诊断</td></tr><tr><td><code>gtpet.pvp.bypass</code></td><td>绕过宠物 PVP 保护判断</td></tr></tbody></table><h2 id="同模板多只宠物" tabindex="-1">同模板多只宠物 <a class="header-anchor" href="#同模板多只宠物" aria-label="Permalink to &quot;同模板多只宠物&quot;">​</a></h2><p>同一玩家可以拥有多只相同模板的宠物。先执行：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/gtpet pets</span></span></code></pre></div><p>再使用列表中的短 ID：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/gtpet summon a1b2c3d4</span></span>
<span class="line"><span>/gtpet rename a1b2c3d4 小白</span></span></code></pre></div><p>如果模板名只匹配到一只宠物，也可以直接使用模板 ID；匹配到多只时必须使用短 ID。</p><h2 id="修改配置并生效" tabindex="-1">修改配置并生效 <a class="header-anchor" href="#修改配置并生效" aria-label="Permalink to &quot;修改配置并生效&quot;">​</a></h2><p>大多数玩法和 GUI 配置修改后执行：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/gtpet reload</span></span></code></pre></div><p>重载成功后重新打开 GUI。已召唤的 <code>PLAYER</code> 宠物如果修改了皮肤、显示方式或逻辑实体，需要先收回再重新召唤。</p><p>以下配置修改后需要重启服务器或重新加载模块：</p><ul><li><code>storage.backend</code></li><li><code>storage.namespace</code></li><li>MySQL/Redis 连接信息</li></ul><h2 id="完整验收" tabindex="-1">完整验收 <a class="header-anchor" href="#完整验收" aria-label="Permalink to &quot;完整验收&quot;">​</a></h2><ol><li>执行 <code>gtpet status</code>，确认 <code>ready=true</code>。</li><li>执行 <code>gtpet give Steve starter_wolf 1</code>。</li><li>玩家打开 <code>/gtpet</code>，确认能看到宠物。</li><li>召唤宠物，走出 4 格以上，确认宠物开始跟随。</li><li>切换 <code>PASSIVE</code>、<code>DEFENSIVE</code> 和 <code>HOLD</code>，确认状态文字改变。</li><li>打开成长、技能、装备和工作页面，确认页面可以正常进入。</li><li>收回宠物并重新召唤，确认同一只宠物的等级、品质和装备没有变化。</li><li>重启测试服，再执行 <code>/gtpet pets</code>，确认宠物记录仍可读取。</li></ol><h2 id="后续教程" tabindex="-1">后续教程 <a class="header-anchor" href="#后续教程" aria-label="Permalink to &quot;后续教程&quot;">​</a></h2><ul><li><a href="/gtpet/templates-storage">模板、存储与召唤</a></li><li><a href="/gtpet/player-model-movement">玩家模型、移动与右键交互</a></li><li><a href="/gtpet/gui-equipment-placeholders">GUI、装备与 PAPI</a></li><li><a href="/gtpet/combat-growth-skills">属性、成长、战斗与技能</a></li><li><a href="/gtpet/breeding-evolution-work">繁育、进化、工作与奖励</a></li><li><a href="/gtpet/coefficients-ai">系数、覆盖与 AI 调整</a></li></ul>`,58)])])}const u=e(o,[["render",l]]);export{g as __pageData,u as default};
